     /// <summary>Ověří odpověď 201 Created a vrátí vytvořené výskyty.</summary>
     private static IReadOnlyList<TodoItemDto> AssertCreatedOccurrences(ActionResult<IReadOnlyList<TodoItemDto>> result)
