         var repository = new InMemoryTodoRepository(new InMemoryTodoOptions(), timeProvider);

         // Ukázkové úkoly vznikly "v minulosti" vůči podvrženému času, ne vůči skutečným hodinám.
         var items = await repository.GetAllAsync();
