     }

     [Fact]
     public async Task Constructor_Seed_CompletedItemsHaveCompletionTime()
     {
         var repository = new InMemoryTodoRepository();

         var items = await repository.GetAllAsync();

         Assert.Contains(items, item => item.IsCompleted);
