     // --- Přidání ------------------------------------------------------------

     [Fact]
     public async Task AddAsync_NewItem_CanBeReadBack()
     {
         var repository = CreateEmptyRepository();
         var item = CreateItem("Napsat Dockerfile");

         await repository.AddAsync(item);

         var stored = await repository.GetByIdAsync(item.Id);
