## `PersistentApiIntegrationTests.cs`

In [PersistentApiIntegrationTests.cs](C:/Users/honza/bench/54-A-20261123-0917/tests/API/PersistentApiIntegrationTests.cs), add this test. It uses two API hosts over the same file and proves that a write through one host invalidates a version previously read through the other:

```csharp
[Fact]
public async Task TwoHosts_SharedFile_WriteInvalidatesVersionReadByOtherHost()
{
    await using var firstFactory = CreateFactory("api-a");
    await using var secondFactory = CreateFactory("api-b");

    using var firstClient = firstFactory.CreateClient();
    using var secondClient = secondFactory.CreateClient();

    var id = await CreateTodoAsync(firstClient, "alice", "Original task");
    var url = $"/api/todos/{id}";

    int staleVersion;
    using (var initial = await firstClient.GetAsync(url))
    {
        initial.EnsureSuccessStatusCode();
        using var document = JsonDocument.Parse(await initial.Content.ReadAsStringAsync());
        staleVersion = document.RootElement.GetProperty("version").GetInt32();
    }

    using (var update = await secondClient.PutAsJsonAsync(url, new
    {
        Version = staleVersion,
        Title = "Current task",
        Description = (string?)null,
        Priority = "Normal",
        IsCompleted = false
    }))
    {
        update.EnsureSuccessStatusCode();

        using var document = JsonDocument.Parse(await update.Content.ReadAsStringAsync());
        Assert.Equal(staleVersion + 1, document.RootElement.GetProperty("version").GetInt32());
    }

    using (var staleUpdate = await firstClient.PutAsJsonAsync(url, new
    {
        Version = staleVersion,
        Title = "Stale overwrite",
        Description = (string?)null,
        Priority = "Normal",
        IsCompleted = false
    }))
    {
        Assert.Equal(System.Net.HttpStatusCode.Conflict, staleUpdate.StatusCode);
    }

    using var current = await firstClient.GetAsync(url);
    current.EnsureSuccessStatusCode();

    using var currentDocument = JsonDocument.Parse(await current.Content.ReadAsStringAsync());
    Assert.Equal("Current task", currentDocument.RootElement.GetProperty("title").GetString());
    Assert.Equal(staleVersion + 1, currentDocument.RootElement.GetProperty("version").GetInt32());
}
```

